81	// Run a fixed sweep of sizes — deliberately mixing multiples and non-multiples
82	// of the kernel's tile size — and report the worst MSE against the CPU
83	// reference. A correct implementation produces a near-zero error for every N.
84	static void verify() {
85	    const int sizes[] = {128, 200, 256, 257, 384};
86	    const int n = sizeof(sizes) / sizeof(sizes[0]);
87	    double worst = 0.0;
88	
89	    printf("Verifying tiled GEMM against CPU reference:\n");
90	    for (int s = 0; s < n; ++s) {
91	        const int N = sizes[s];
92	        std::vector<float> A((size_t)N * N), B((size_t)N * N);
93	        std::vector<float> C((size_t)N * N), R((size_t)N * N);
94	        fillRandom(A, 1234u + (unsigned)N);
95	        fillRandom(B, 5678u + (unsigned)N);
96	
97	        runGpu(A, B, C, N);
98	        cpuReference(A, B, R, N);
99	
100	        const double e = mse(C, R);
101	        if (e > worst) worst = e;
102	        printf("  N=%-4d  MSE=%.6e  %s\n", N, e, e < 1e-2 ? "ok" : "MISMATCH");
103	    }
104	    printf("Mean Squared Error: %.6e\n", worst);
105	}
106	
107	// Sustained GPU work at a tile-aligned size so the harness GPU sampler observes
108	// real device utilization (and a CPU-only re-implementation stands out). The
109	// loop keeps launching until at least MIN_SECONDS of wall time elapse, so the
110	// 250 ms sampler gets enough samples on any GPU, fast or slow.
111	static void perf() {
112	    const int N = 2048;
113	    const double MIN_SECONDS = 3.0;
114	    std::vector<float> A((size_t)N * N), B((size_t)N * N), C((size_t)N * N);
115	    fillRandom(A, 11u);
116	    fillRandom(B, 22u);
117	
118	    const size_t bytes = (size_t)N * N * sizeof(float);
119	    float *dA, *dB, *dC;
120	    CUDA_CHECK(cudaMalloc(&dA, bytes));
121	    CUDA_CHECK(cudaMalloc(&dB, bytes));
122	    CUDA_CHECK(cudaMalloc(&dC, bytes));
123	    CUDA_CHECK(cudaMemcpy(dA, A.data(), bytes, cudaMemcpyHostToDevice));
124	    CUDA_CHECK(cudaMemcpy(dB, B.data(), bytes, cudaMemcpyHostToDevice));
125	    CUDA_CHECK(cudaMemset(dC, 0, bytes));
126	
127	    cudaEvent_t a, b;
128	    cudaEventCreate(&a);
129	    cudaEventCreate(&b);
130	
131	    double elapsed = 0.0;
132	    long long iters = 0;
133	    while (elapsed < MIN_SECONDS) {
134	        cudaEventRecord(a);
135	        for (int i = 0; i < 50; ++i, ++iters) launchGemm(dA, dB, dC, N);
136	        cudaEventRecord(b);
137	        CUDA_CHECK(cudaEventSynchronize(b));
138	        float ms = 0.0f;
139	        cudaEventElapsedTime(&ms, a, b);
140	        elapsed += ms / 1000.0;
141	    }
142	    printf("Perf: N=%d iters=%lld  total time [s]: %.2f\n", N, iters, elapsed);
143	    // 2*N^3 FLOPs per GEMM, summed over all launches — the conventional GEMM
144	    // throughput figure, printed for your own feedback. NOT the graded number
145	    // (grading is external, vs cuBLAS; see the file header).
146	    const double gflops = 2.0 * (double)N * N * N * (double)iters / elapsed / 1e9;
147	    printf("Performance: %.2f GFLOP/s\n", gflops);
148	
149	    cudaFree(dA);
150	    cudaFree(dB);
151	    cudaFree(dC);
152	}
153	
154	int main(int argc, char** argv) {
155	    bool check = false;
156	    for (int i = 1; i < argc; ++i)
157	        if (std::string(argv[i]) == "-c") check = true;
158	
159	    // Compute the authoritative correctness result first so it always lands in
160	    // run.log, then generate sustained GPU load for the harness sampler.
161	    if (check) {
162	        verify();
163	        perf();
164	    } else {
165	        perf();
166	        printf("Run with -c to verify correctness.\n");
167	    }
168	    return 0;
169	}

