#include <cuda_runtime.h>

#define TILE 64
#define FRAG 4

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    const int numTiles = (N + TILE - 1) / TILE;
    const int ty = threadIdx.y;
    const int tx = threadIdx.x;

    // Thread's output position (top-left of 4x4 fragment)
    const int row = blockIdx.y * TILE + ty * FRAG;
    const int col = blockIdx.x * TILE + tx * FRAG;

    // 4x4 accumulator fragment
    float a00 = 0.0f, a01 = 0.0f, a02 = 0.0f, a03 = 0.0f;
    float a10 = 0.0f, a11 = 0.0f, a12 = 0.0f, a13 = 0.0f;
    float a20 = 0.0f, a21 = 0.0f, a22 = 0.0f, a23 = 0.0f;
    float a30 = 0.0f, a31 = 0.0f, a32 = 0.0f, a33 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        // --- Load A tile (32-bit coalesced, row-major) ---
        // Thread loads 4 elements from As[ty*4+dy][tx*4+dx]
        // Global: A[(row+dy)*N + (t*TILE + tx*4 + dx)]
        {
            const int rowBase = row;
            const int rowOff0 = rowBase * N;
            const int rowOff1 = rowOff0 + N;
            const int rowOff2 = rowOff1 + N;
            const int rowOff3 = rowOff2 + N;
            const int sc0 = tx * FRAG;

            // dy=0: row = rowBase
            {
                const int sa = ty * FRAG + 0;
                const int gc0 = t * TILE + sc0;
                if (rowBase < N) {
                    if (gc0 + 0 < N) As[sa][sc0 + 0] = A[rowOff0 + gc0 + 0];
                    else As[sa][sc0 + 0] = 0.0f;
                    if (gc0 + 1 < N) As[sa][sc0 + 1] = A[rowOff0 + gc0 + 1];
                    else As[sa][sc0 + 1] = 0.0f;
                    if (gc0 + 2 < N) As[sa][sc0 + 2] = A[rowOff0 + gc0 + 2];
                    else As[sa][sc0 + 2] = 0.0f;
                    if (gc0 + 3 < N) As[sa][sc0 + 3] = A[rowOff0 + gc0 + 3];
                    else As[sa][sc0 + 3] = 0.0f;
                } else {
                    As[sa][sc0 + 0] = 0.0f;
                    As[sa][sc0 + 1] = 0.0f;
                    As[sa][sc0 + 2] = 0.0f;
                    As[sa][sc0 + 3] = 0.0f;
                }
            }
            // dy=1: row = rowBase + 1
            {
                const int sa = ty * FRAG + 1;
                const int gc0 = t * TILE + sc0;
                if (rowBase + 1 < N) {
                    if (gc0 + 0 < N) As[sa][sc0 + 0] = A[rowOff1 + gc0 + 0];
                    else As[sa][sc0 + 0] = 0.0f;
                    if (gc0 + 1 < N) As[sa][sc0 + 1] = A[rowOff1 + gc0 + 1];
                    else As[sa][sc0 + 1] = 0.0f;
                    if (gc0 + 2 < N) As[sa][sc0 + 2] = A[rowOff1 + gc0 + 2];
                    else As[sa][sc0 + 2] = 0.0f;
                    if (gc0 + 3 < N) As[sa][sc0 + 3] = A[rowOff1 + gc0 + 3];
                    else As[sa][sc0 + 3] = 0.0f;
                } else {
                    As[sa][sc0 + 0] = 0.0f;
                    As[sa][sc0 + 1] = 0.0f;
                    As[sa][sc0 + 2] = 0.0f;
                    As[sa][sc0 + 3] = 0.0f;
                }
            }
            // dy=2: row = rowBase + 2
            {
                const int sa = ty * FRAG + 2;
                const int gc0 = t * TILE + sc0;
                if (rowBase + 2 < N) {
                    if (gc0 + 0 < N) As[sa][sc0 + 0] = A[rowOff2 + gc0 + 0];
                    else As[sa][sc0 + 0] = 0.0f;
                    if (gc0 + 1 < N) As[sa][sc0 + 1] = A[rowOff2 + gc0 + 1];
                    else As[sa][sc0 + 1] = 0.0f;
                    if (gc0 + 2 < N) As[sa][sc0 + 2] = A[rowOff2 + gc0 + 2];
                    else As[sa][sc0 + 2] = 0.0f;
                    if (gc0 + 3 < N) As[sa][sc0 + 3] = A[rowOff2 + gc0 + 3];
                    else As[sa][sc0 + 3] = 0.0f;
                } else {
                    As[sa][sc0 + 0] = 0.0f;
                    As[sa][sc0 + 1] = 0.0f;
                    As[sa][sc0 + 2] = 0.0f;
                    As[sa][sc0 + 3] = 0.0f;
                }
            }
            // dy=3: row = rowBase + 3
            {
                const int sa = ty * FRAG + 3;
                const int gc0 = t * TILE + sc0;
                if (rowBase + 3 < N) {
                    if (gc0 + 0 < N) As[sa][sc0 + 0] = A[rowOff3 + gc0 + 0];
                    else As[sa][sc0 + 0] = 0.0f;
                    if (gc0 + 1 < N) As[sa][sc0 + 1] = A[rowOff3 + gc0 + 1];
                    else As[sa][sc0 + 1] = 0.0f;
                    if (gc0 + 2 < N) As[sa][sc0 + 2] = A[rowOff3 + gc0 + 2];
                    else As[sa][sc0 + 2] = 0.0f;
                    if (gc0 + 3 < N) As[sa][sc0 + 3] = A[rowOff3 + gc0 + 3];
                    else As[sa][sc0 + 3] = 0.0f;
                } else {
                    As[sa][sc0 + 0] = 0.0f;
                    As[sa][sc0 + 1] = 0.0f;
                    As[sa][sc0 + 2] = 0.0f;
                    As[sa][sc0 + 3] = 0.0f;
                }
            }
        }

        // --- Load B tile (32-bit coalesced, row-major) ---
        // Thread loads 4 elements from Bs[ty*4+dy][tx*4+dx]
        // Global: B[(t*TILE + ty*4 + dy)*N + (col + tx*4 + dx)]
        {
            const int grBase = t * TILE + ty * FRAG;
            const int sc0 = tx * FRAG;

            // dy=0: br = grBase
            {
                const int sb = ty * FRAG + 0;
                if (grBase < N) {
                    const int bc0 = col + sc0;
                    if (bc0 + 0 < N) Bs[sb][sc0 + 0] = B[grBase * N + bc0 + 0];
                    else Bs[sb][sc0 + 0] = 0.0f;
                    if (bc0 + 1 < N) Bs[sb][sc0 + 1] = B[grBase * N + bc0 + 1];
                    else Bs[sb][sc0 + 1] = 0.0f;
                    if (bc0 + 2 < N) Bs[sb][sc0 + 2] = B[grBase * N + bc0 + 2];
                    else Bs[sb][sc0 + 2] = 0.0f;
                    if (bc0 + 3 < N) Bs[sb][sc0 + 3] = B[grBase * N + bc0 + 3];
                    else Bs[sb][sc0 + 3] = 0.0f;
                } else {
                    Bs[sb][sc0 + 0] = 0.0f;
                    Bs[sb][sc0 + 1] = 0.0f;
                    Bs[sb][sc0 + 2] = 0.0f;
                    Bs[sb][sc0 + 3] = 0.0f;
                }
            }
            // dy=1: br = grBase + 1
            {
                const int sb = ty * FRAG + 1;
                if (grBase + 1 < N) {
                    const int bc0 = col + sc0;
                    if (bc0 + 0 < N) Bs[sb][sc0 + 0] = B[(grBase + 1) * N + bc0 + 0];
                    else Bs[sb][sc0 + 0] = 0.0f;
                    if (bc0 + 1 < N) Bs[sb][sc0 + 1] = B[(grBase + 1) * N + bc0 + 1];
                    else Bs[sb][sc0 + 1] = 0.0f;
                    if (bc0 + 2 < N) Bs[sb][sc0 + 2] = B[(grBase + 1) * N + bc0 + 2];
                    else Bs[sb][sc0 + 2] = 0.0f;
                    if (bc0 + 3 < N) Bs[sb][sc0 + 3] = B[(grBase + 1) * N + bc0 + 3];
                    else Bs[sb][sc0 + 3] = 0.0f;
                } else {
                    Bs[sb][sc0 + 0] = 0.0f;
                    Bs[sb][sc0 + 1] = 0.0f;
                    Bs[sb][sc0 + 2] = 0.0f;
                    Bs[sb][sc0 + 3] = 0.0f;
                }
            }
            // dy=2: br = grBase + 2
            {
                const int sb = ty * FRAG + 2;
                if (grBase + 2 < N) {
                    const int bc0 = col + sc0;
                    if (bc0 + 0 < N) Bs[sb][sc0 + 0] = B[(grBase + 2) * N + bc0 + 0];
                    else Bs[sb][sc0 + 0] = 0.0f;
                    if (bc0 + 1 < N) Bs[sb][sc0 + 1] = B[(grBase + 2) * N + bc0 + 1];
                    else Bs[sb][sc0 + 1] = 0.0f;
                    if (bc0 + 2 < N) Bs[sb][sc0 + 2] = B[(grBase + 2) * N + bc0 + 2];
                    else Bs[sb][sc0 + 2] = 0.0f;
                    if (bc0 + 3 < N) Bs[sb][sc0 + 3] = B[(grBase + 2) * N + bc0 + 3];
                    else Bs[sb][sc0 + 3] = 0.0f;
                } else {
                    Bs[sb][sc0 + 0] = 0.0f;
                    Bs[sb][sc0 + 1] = 0.0f;
                    Bs[sb][sc0 + 2] = 0.0f;
                    Bs[sb][sc0 + 3] = 0.0f;
                }
            }
            // dy=3: br = grBase + 3
            {
                const int sb = ty * FRAG + 3;
                if (grBase + 3 < N) {
                    const int bc0 = col + sc0;
                    if (bc0 + 0 < N) Bs[sb][sc0 + 0] = B[(grBase + 3) * N + bc0 + 0];
                    else Bs[sb][sc0 + 0] = 0.0f;
                    if (bc0 + 1 < N) Bs[sb][sc0 + 1] = B[(grBase + 3) * N + bc0 + 1];
                    else Bs[sb][sc0 + 1] = 0.0f;
                    if (bc0 + 2 < N) Bs[sb][sc0 + 2] = B[(grBase + 3) * N + bc0 + 2];
                    else Bs[sb][sc0 + 2] = 0.0f;
                    if (bc0 + 3 < N) Bs[sb][sc0 + 3] = B[(grBase + 3) * N + bc0 + 3];
                    else Bs[sb][sc0 + 3] = 0.0f;
                } else {
                    Bs[sb][sc0 + 0] = 0.0f;
                    Bs[sb][sc0 + 1] = 0.0f;
                    Bs[sb][sc0 + 2] = 0.0f;
                    Bs[sb][sc0 + 3] = 0.0f;
                }
            }
        }

        __syncthreads();

        // --- Compute: unrolled k-loop, 16 FMAs per iteration ---
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            a00 += As[ty * FRAG + 0][k] * Bs[k][tx * FRAG + 0];
            a01 += As[ty * FRAG + 0][k] * Bs[k][tx * FRAG + 1];
            a02 += As[ty * FRAG + 0][k] * Bs[k][tx * FRAG + 2];
            a03 += As[ty * FRAG + 0][k] * Bs[k][tx * FRAG + 3];
            a10 += As[ty * FRAG + 1][k] * Bs[k][tx * FRAG + 0];
            a11 += As[ty * FRAG + 1][k] * Bs[k][tx * FRAG + 1];
            a12 += As[ty * FRAG + 1][k] * Bs[k][tx * FRAG + 2];
            a13 += As[ty * FRAG + 1][k] * Bs[k][tx * FRAG + 3];
            a20 += As[ty * FRAG + 2][k] * Bs[k][tx * FRAG + 0];
            a21 += As[ty * FRAG + 2][k] * Bs[k][tx * FRAG + 1];
            a22 += As[ty * FRAG + 2][k] * Bs[k][tx * FRAG + 2];
            a23 += As[ty * FRAG + 2][k] * Bs[k][tx * FRAG + 3];
            a30 += As[ty * FRAG + 3][k] * Bs[k][tx * FRAG + 0];
            a31 += As[ty * FRAG + 3][k] * Bs[k][tx * FRAG + 1];
            a32 += As[ty * FRAG + 3][k] * Bs[k][tx * FRAG + 2];
            a33 += As[ty * FRAG + 3][k] * Bs[k][tx * FRAG + 3];
        }

        __syncthreads();
    }

    // --- Store 4x4 output fragment ---
    const int r0 = row;
    const int c0 = col;
    if (r0 + 0 < N && c0 + 0 < N) C[(r0 + 0) * N + (c0 + 0)] = a00;
    if (r0 + 0 < N && c0 + 1 < N) C[(r0 + 0) * N + (c0 + 1)] = a01;
    if (r0 + 0 < N && c0 + 2 < N) C[(r0 + 0) * N + (c0 + 2)] = a02;
    if (r0 + 0 < N && c0 + 3 < N) C[(r0 + 0) * N + (c0 + 3)] = a03;
    if (r0 + 1 < N && c0 + 0 < N) C[(r0 + 1) * N + (c0 + 0)] = a10;
    if (r0 + 1 < N && c0 + 1 < N) C[(r0 + 1) * N + (c0 + 1)] = a11;
    if (r0 + 1 < N && c0 + 2 < N) C[(r0 + 1) * N + (c0 + 2)] = a12;
    if (r0 + 1 < N && c0 + 3 < N) C[(r0 + 1) * N + (c0 + 3)] = a13;
    if (r0 + 2 < N && c0 + 0 < N) C[(r0 + 2) * N + (c0 + 0)] = a20;
    if (r0 + 2 < N && c0 + 1 < N) C[(r0 + 2) * N + (c0 + 1)] = a21;
    if (r0 + 2 < N && c0 + 2 < N) C[(r0 + 2) * N + (c0 + 2)] = a22;
    if (r0 + 2 < N && c0 + 3 < N) C[(r0 + 2) * N + (c0 + 3)] = a23;
    if (r0 + 3 < N && c0 + 0 < N) C[(r0 + 3) * N + (c0 + 0)] = a30;
    if (r0 + 3 < N && c0 + 1 < N) C[(r0 + 3) * N + (c0 + 1)] = a31;
    if (r0 + 3 < N && c0 + 2 < N) C[(r0 + 3) * N + (c0 + 2)] = a32;
