{"content":"#include "gemm.cuh"

#include <cuda_runtime.h>

#define TILE 64
#define FRAG 4
#define PAD 1  // 1-element padding to avoid shared memory bank conflicts

__device__ __forceinline__ float ldg(const float* p) {
#if __CUDA_ARCH__ >= 700
    return __ldg(p);
#else
    return *p;
#endif
}

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    __shared__ float As[TILE][TILE + PAD];
    __shared__ float Bs[TILE][TILE + PAD];

    const int numTiles = (N + TILE - 1) / TILE;
    const int ty = threadIdx.y;
    const int tx = threadIdx.x;

    const int row = blockIdx.y * TILE + ty * FRAG;
    const int col = blockIdx.x * TILE + tx * FRAG;

    float a00 = 0.0f, a01 = 0.0f, a02 = 0.0f, a03 = 0.0f;
    float a10 = 0.0f, a11 = 0.0f, a12 = 0.0f, a13 = 0.0f;
    float a20 = 0.0f, a21 = 0.0f, a22 = 0.0f, a23 = 0.0f;
    float a30 = 0.0f, a31 = 0.0f, a32 = 0.0f, a33 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        const int sc = tx * FRAG;
        const int gc = t * TILE + sc;

        // Load A tile (row-major, coalesced global loads via __ldg)
        #pragma unroll
        for (int dy = 0; dy < FRAG; ++dy) {
            const int ar = row + dy;
            #pragma unroll
            for (int dx = 0; dx < FRAG; ++dx) {
                const int ac = gc + dx;
                if (ar < N && ac < N)
                    As[ty * FRAG + dy][sc + dx] = ldg(&A[ar * N + ac]);
                else
                    As[ty * FRAG + dy][sc + dx] = 0.0f;
            }
        }

        // Load B tile (coalesced global loads via __ldg)
        const int grb = t * TILE + ty * FRAG;
        #pragma unroll
        for (int dy = 0; dy < FRAG; ++dy) {
            const int br = grb + dy;
            #pragma unroll
            for (int dx = 0; dx < FRAG; ++dx) {
                const int bc = col + dx;
                if (br < N && bc < N)
                    Bs[ty * FRAG + dy][sc + dx] = ldg(&B[br * N + bc]);
                else
                    Bs[ty * FRAG + dy][sc + dx] = 0.0f;
            }
        }

        __syncthreads();

