{"content":"#include "gemm.cuh"

#include <cuda_runtime.h>

#define TILE 64
#define FRAG 4

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    __shared__ float As[2][TILE][TILE];
    __shared__ float Bs[2][TILE][TILE];

    const int numTiles = (N + TILE - 1) / TILE;
    const int ty = threadIdx.y;
    const int tx = threadIdx.x;

    const int row = blockIdx.y * TILE + ty * FRAG;
    const int col = blockIdx.x * TILE + tx * FRAG;

    float a00 = 0.0f, a01 = 0.0f, a02 = 0.0f, a03 = 0.0f;
    float a10 = 0.0f, a11 = 0.0f, a12 = 0.0f, a13 = 0.0f;
    float a20 = 0.0f, a21 = 0.0f, a22 = 0.0f, a23 = 0.0f;
    float a30 = 0.0f, a31 = 0.0f, a32 = 0.0f, a33 = 0.0f;

    // Load first tile
    {
        const int sc = tx * FRAG;
        const int gc = 0 * TILE + sc;
        #pragma unroll
        for (int dy = 0; dy < FRAG; ++dy) {
            const int ar = row + dy;
            #pragma unroll
            for (int dx = 0; dx < FRAG; ++dx) {
                As[0][ty * FRAG + dy][sc + dx] =
                    (ar < N && gc + dx < N) ? A[ar * N + gc + dx] : 0.0f;
            }
        }
        const int grb = 0 * TILE + ty * FRAG;
        #pragma unroll
        for (int dy = 0; dy < FRAG; ++dy) {
            const int br = grb + dy;
            #pragma unroll
            for (int dx = 0; dx < FRAG; ++dx) {
                Bs[0][ty * FRAG + dy][sc + dx] =
                    (br < N && col + dx < N) ? B[br * N + col + dx] : 0.0f;
            }
        }
        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            a00 += As[0][ty * FRAG + 0][k] * Bs[0][k][sc + 0];
            a01 += As[0][ty * FRAG + 0][k] * Bs[0][k][sc + 1];
            a02 += As[0][ty * FRAG + 0][k] * Bs[0][k][sc + 2];
            a03 += As[0][ty * FRAG + 0][k] * Bs[0][k][sc + 3];
            a10 += As[0][ty * FRAG + 1][k] * Bs[0][k][sc + 0];
            a11 += As[0][ty * FRAG + 1][k] * Bs[0][k][sc + 1];
            a12 += As[0][ty * FRAG + 1][k] * Bs[0][k][sc + 2];
            a13 += As[0][ty * FRAG + 1][k] * Bs[0][k][sc + 3];
            a20 += As[0][ty * FRAG + 2][k] * Bs[0][k][sc + 0];
            a21 += As[0][ty * FRAG + 2][k] * Bs[0][k][sc + 1];
            a22 += As[0][ty * FRAG + 2][k] * Bs[0][k][sc + 2];
            a23 += As[0][ty * FRAG + 2][k] * Bs[0][k][sc + 3];
            a30 += As[0][ty * FRAG + 3][k] * Bs[0][k][sc + 0];
            a31 += As[0][ty * FRAG + 3][k] * Bs[0][k][sc + 1];
            a32 += As[0][ty * FRAG + 3][k] * Bs[0][k][sc + 2];
            a33 += As[0][ty * FRAG + 3][k] * Bs[0][k][sc + 3];
        }
        __syncthreads();
    }

    for (int t = 1; t < numTiles; ++t) {
        const int buf = t & 1;
        const int sc = tx * FRAG;
        const int gc = t * TILE + sc;

        // Load next tile while previous is being computed
        #pragma unroll
        for (int dy = 0; dy < FRAG; ++dy) {
            const int ar = row + dy;
            #pragma unroll
            for (int dx = 0; dx < FRAG; ++dx) {
                As[buf][ty * FRAG + dy][sc + dx] =
                    (ar < N && gc + dx < N) ? A[ar * N + gc + dx] : 0.0f;
            }
        }
        const int grb = t * TILE + ty * FRAG;
        #pragma unroll
        for (int dy = 0; dy < FRAG; ++dy) {
            const int br = grb + dy;
            #pragma unroll
            for (int dx = 0; dx < FRAG; ++dx) {
                Bs[buf][ty * FRAG + dy][sc + dx] =
                    (br < N && col + dx < N) ? B[br * N + col + dx] : 0.0f;
            }
        }
        __syncthreads();

        int prev = 1 - buf;
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            a00 += As[prev][ty * FRAG + 0][k] * Bs[prev][k][sc + 0];
            a01 += As[prev][ty * FRAG + 0][k] * Bs[prev][k][sc + 1];
            a02 += As[prev][ty * FRAG + 0][k] * Bs[prev][k][sc + 2];
            a03 += As[prev][ty * FRAG + 0][k] * Bs[prev][k][sc + 3];
            a10 += As[prev][ty * FRAG + 1][k] * Bs[prev][k][sc + 0];
            a11 += As[prev][ty * FRAG + 1][k] * Bs[prev][k][sc + 1];
            a12 += As[prev][ty * FRAG + 1][k] * Bs[prev][k][sc + 2];
            a13 += As[prev][ty * FRAG + 1][k] * Bs[prev][k][sc + 3];
            a20 += As[prev][ty * FRAG + 2][k] * Bs[prev][k][sc + 0];
            a21 += As[prev][ty * FRAG + 2][k] * Bs[prev][k][sc + 1];
            a22 += As[prev][ty * FRAG + 2][k] * Bs[prev][k][sc + 2];
            a23 += As[prev][ty * FRAG + 2][k] * Bs[prev][k][sc + 3];
            a30 += As[prev][ty * FRAG + 3][k] * Bs[prev][k][sc + 0];
            a31 += As[prev][ty * FRAG + 3][k] * Bs[prev][k][sc + 1];
            a32 += As[prev][ty * FRAG + 3][k] * Bs[prev][k][sc + 2];
            a33 += As[prev][ty * FRAG + 3][k] * Bs[prev][k][sc + 3];
        }
        __syncthreads();
    }

    // Store 4x4 output fragment
    const int r0 = row;
    const int c0 = col;
    if (r0 + 0 < N && c0 + 0 < N) C[(r0 + 0) * N + (c0 + 0)] = a00;
    if (r0 + 0 < N && c0 + 1 < N) C[(r0 + 0) * N + (c0 + 1)] = a01;
    if (r0 + 0 < N && c0 + 2 < N) C[(r0 + 0) * N + (c0 + 2)] = a02;
    if (r0 + 0 < N && c0 + 3 < N) C[(r0 + 0) * N + (c0 + 3)] = a03;
    if (r0 + 1 < N && c0 + 0 < N) C[(r0 + 1) * N + (c0 + 0)] = a10;
    if (r0 + 1 < N && c0 + 1 < N) C[(r0 + 1) * N + (c0 + 1)] = a11;
    if (r0 + 1 < N && c0 + 2 < N) C[(r0 + 1) * N + (c0 + 2)] = a12;
    if (r0 + 1 < N && c0 + 3 < N) C[(r0 + 1) * N + (c0 + 3)] = a13;
    if (r0 + 2 < N && c0 + 0 < N) C[(r0 + 2) * N + (c0 + 0)] = a20;
    if (r0 + 2 < N && c0 + 1 < N) C[(r0 + 2) * N + (c0 + 1)] = a21;
    if (r0 + 2 < N && c0 + 2 < N) C[(r0 + 2) * N + (c0 + 2)] = a22;
    if (r0 + 2 < N && c0 + 3 < N) C[(r0 + 2) * N + (c0 + 3)] = a23;
    if (r0 + 3 < N && c0 + 0 < N) C[(r0 + 3) * N + (c0 + 0)] = a30;
    if (r0 + 3 < N && c0 + 1 < N) C[(r0 + 3) * N + (c0 + 1)] = a31;
    if (r0 + 3 < N && c0 + 2 < N) C[(r0 + 3) * N + (c0 + 2)] = a32;
    if (r0 + 3 < N && c0 + 3 < N) C[(r0 + 3) * N + (c0 + 3)] = a33;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    if (N <= 0) return;
    dim3 block(TILE / FRAG, TILE / FRAG);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
