{"content":"#include "gemm.cuh"

#include <cuda_runtime.h>
#include <mma.h>
using namespace nvcuda;

// ============================================================================
// Tensor-core tiled GEMM on A40 (sm_86)
//
// Grid: each block handles a TILE×TILE output tile.
// Block: 4 warp groups (4×4), each group computes a 16×16 sub-tile of C.
// Each warp group loads 4 wmma fragments of A and 4 of B into shared memory.
// ============================================================================

#define TILE 64
#define MMA_SIZE 16
#define WARPS_PER_TILE (TILE / MMA_SIZE)   // 4
#define TOTAL_WARPS (WARPS_PER_TILE * WARPS_PER_TILE)  // 16

// Shared memory layout:
// As[k][64*ty + tx] for k=0..WARPS_PER_TILE-1 (one 64x64 tile per warp-group of A)
// Bs[k][64*ty + tx] for k=0..WARPS_PER_TILE-1 (one 64x64 tile per warp-group of B)
// Total smem: 2 * WARPS_PER_TILE * 64 * 64 * 4 = 2 * 4 * 4096 * 4 = 128KB

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    extern __shared__ char sharedMem[];

    // 4 warp-groups for A: each loads a 16×64 sub-tile per k-iteration
    // 4 warp-groups for B: each loads a 64×16 sub-tile per k-iteration
    float* As = reinterpret_cast<float*>(sharedMem);
    float* Bs = As + WARPS_PER_TILE * TILE * TILE;

    const int numTiles = (N + TILE - 1) / TILE;
    const int warpId = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;

    // Warp-group coordinates within block
    const int wgRow = warpId / WARPS_PER_TILE;  // 0..3
    const int wgCol = warpId % WARPS_PER_TILE;   // 0..3

    // Global output position of this warp-group
    const int outRow = blockIdx.y * TILE + wgRow * MMA_SIZE;
    const int outCol = blockIdx.x * TILE + wgCol * MMA_SIZE;

    // Each warp group computes:
    // C[outRow..outRow+15][outCol..outCol+15] =
    //   sum_k A[outRow..outRow+15][tileCol+k*64..tileCol+k*64+63] *
    //         B[tileRow+k*64..tileRow+k*64+63][outCol..outCol+15]
    // where tileRow = blockIdx.y * TILE, tileCol = blockIdx.x * TILE

    // Each warp group loads WARPS_PER_TILE wmma matrix fragments from A and B.
    // Warp group (wgRow, wgCol) loads:
    //   A_fragments[w]: A[outRow..outRow+15][tileCol + w*TILE .. tileCol + w*TILE + 63]
    //   B_fragments[w]: B[tileRow + w*TILE .. tileRow + w*TILE + 63][outCol..outCol+15]
    // where w = 0..WARPS_PER_TILE-1

    // Thread within warp (0-31). Each thread loads 2 wmma elements (2×4 = 8 float32 per wmma frag).
    // Wait, wmma fragment is 16×16 matrix_a/b = 256 floats. Each warp has 32 threads.
    // Each thread loads 256/32 = 8 floats from each wmma fragment.
    // Total per warp group: 4 A fragments + 4 B fragments = 8 × 256 × 4 bytes = 8 KB per warp group
    // Total for all warp groups: 16 × 8 KB = 128 KB. That's too much for shared memory (max 164KB per SM).

    // Better: each warp group loads one A fragment and one B fragment at a time.
    // Shared memory has TILE×TILE entries for A and B, shared by all warp groups.
    // A's TILE×TILE tile = 64×64 = 4096 floats = 16KB
    // B's TILE×TILE tile = 64×64 = 4096 floats = 16KB
    // Total: 32KB. Much better.

    // Shared memory layout:
    // As[TILE][TILE] and Bs[TILE][TILE] - each stores one full TILE×TILE tile
    // As already has TILE entries of TILE floats each.

    // Each warp group loads 4 fragments:
    //   A[wgRow * MMA_SIZE .. +15][w*TILE + ...] from global → As
    //   B[w*TILE + ...][wgCol * MMA_SIZE .. +15] from global → Bs
    // Then performs 4 MMA operations.

    // But we need to ensure no warp-group conflicts when loading.
    // Let each warp group load its own portion using __syncthreads().

    // Actually the simplest approach: all 16 warps cooperatively load the full
    // 64×64 A tile and 64×64 B tile into shared memory (32KB total).
    // Then each warp group loads from shared memory and performs MMA.

    __syncthreads();

    // All warps cooperatively load A and B tiles
    // Thread idx (0-511), each loads 2 elements from A and 2 from B (8 bytes each = 16 bytes)

    // A tile: global tile at (t, t) → A[tileStart * N + t*N] with shape 64×64
    // B tile: global tile at (t, t) → B[tileStart * N + t*N] with shape 64×64
    // Each warp group (wgRow, wgCol) is responsible for rows [wgRow*16 .. +15] in A and
    // columns [wgCol*16 .. +15] in B

    for (int t = 0; t < numTiles; ++t) {
        const int tileStart = t * TILE;

        // --- Cooperative load of A tile ---
        // Each warp group loads its 16×64 rows of the A tile
        // wgRow = 0..3: rows [0..15], [16..31], [32..47], [48..63] relative to tile
        const int tileA_row = tileStart + wgRow * MMA_SIZE;
        // Thread within warp: each thread loads 2 floats from A (row-major, coalesced)
        const int threadRow = lane / 2;  // 0..15
        const int threadCol = lane % 2;  // 0..1
        // Load 2 consecutive elements in the A tile row
        // A tile[wgRow*16 + threadRow] [k*16 + threadCol*2 + 0..1]
        // But we need to load from global memory, not shared yet.

        // Wait - the A tile at step t has dimensions TILE×TILE. We need 64×64.
        // Each warp group (wgRow, wgCol) needs:
        //   A fragments: A[outRow + wgRow*16 .. +15][tileStart + w*16 .. +63] for w=0..3
        //   That's 16×64 = 1024 elements = 16 warps to load coalesced.
        //   Each warp loads 16×4 = 64 elements. 16 warps × 64 = 1024.
        //   But warp loading needs coalesced access: each warp loads a 16×4 block.
        //   Thread loads 2 elements (4 bytes × 2 = 8 bytes per thread).
        //   Warps 0-3 load: rows 0-63, cols [0+threadCol*2 + lane/2*64]
        //   Hmm, coalescing is complex with 16 warps.

        // Let me use a simpler load scheme: each thread loads 4 elements
        // (16 bytes, one 4-wide load). With 512 threads, we load 2048 elements = 64*64*4.
        // But we also need to load B. Total: 2048*2 = 4096 elements = 64*64*8.
        // That requires two loops or each thread loads 8 elements (32 bytes).

        // Each thread loads 8 elements from A (row-major) = 32 bytes
        // Global: A[(tileA_row + threadRow) * N + tileStart + w*MMA_SIZE + threadCol*4 + lane/8]
        // No, this is getting too complex. Let me use a simple row-major load.

        // Simpler: each thread loads 2 elements from A and 2 from B using __ldg.
        // Thread idx maps to a unique (row, col) in the TILE×TILE tile.
        // Row = idx / TILE, Col = idx % TILE.
        // But TILE=64 and we have 512 threads (16*32). 512 = 8*64. So 8 threads per tile row.
        // Each thread loads 8 elements (row = tileA_row + threadRow, threadRow = idx % TILE)
        // No wait, 512 threads / 64 cols = 8 threads per row. Each loads 1 element.
        // We need 8 loads per element → 8 threads per row, each loading 1 element.
        // That's 64*64 elements, 8 threads per row, each loading 1 element.
        // Threads are organized as 16 warps * 32 = 512.
        // Row = lane (0-31) for each warp, warpId determines the row offset.
        // Actually: threadIdx.x = warpId * 32 + lane
        // threadRow = threadIdx.x % TILE = lane (since TILE=64, and we need 64 rows)
        // threadCol = threadIdx.x / TILE
        // threadRow = lane = 0..31
        // threadCol = warpId = 0..15
        // This gives us rows 0..31 and cols 0..15. That's only 32*16 = 512 elements!
        // We need to cover 64*64 = 4096 elements.
        // 512 threads / 32 = 16 warps. Each warp has 32 threads.
        // If threadRow = lane (0-31), then 16 warps × 32 lanes = 512 unique threads,
        // but that only covers 512 elements, not 4096.

        // For A tile load: each warp group handles 16 rows × 64 cols = 1024 elements.
        // 4 warp groups × 1024 = 4096. ✓
        // Within a warp group: 4 warps × 32 threads = 128 threads.
        // 128 threads need to load 1024 elements → 8 elements per thread.
        // Coalesced: each warp loads 4 rows × 32 cols × 8 bytes = 1024 bytes.
        // This is doable!
    }

    // OK, this approach is getting way too complex. Let me try a completely
    // different strategy: use a 1D grid of warps for simple coalesced loads.

    // For now, fall through to the end of the for loop.
    // This is a placeholder - the actual computation below is not reached.
}

// ============================================================================
// Simple but effective shared-memory tiled GEMM with register tiling
// TILE=64, FRAG=4: 16×16=256 threads, register-tiled 4×4 accumulation
// ============================================================================

#define USE_SIMPLE 1

#if USE_SIMPLE
#define SIMPLE_TILE 64
#define SIMPLE_FRAG 4

__global__ void simpleKernel(const float* __restrict__ A,
                             const float* __restrict__ B,
                             float* __restrict__ C,
                             int N) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];
    const int numTiles = (N + TILE - 1) / TILE;
    const int ty = threadIdx.y, tx = threadIdx.x;
    const int row = blockIdx.y * TILE + ty * FRAG;
    const int col = blockIdx.x * TILE + tx * FRAG;
    float a00=0,a01=0,a02=0,a03=0,a10=0,a11=0,a12=0,a13=0;
    float a20=0,a21=0,a22=0,a23=0,a30=0,a31=0,a32=0,a33=0;
    for (int t=0; t<numTiles; ++t) {
        const int sc=tx*FRAG, gc=t*TILE+sc;
        #pragma unroll
        for (int dy=0; dy<FRAG; ++dy) {
            const int ar=row+dy;
            #pragma unroll
            for (int dx=0; dx<FRAG; ++dx)
                As[ty*FRAG+dy][sc+dx]=(ar<N&&gc+dx<N)?A[ar*N+gc+dx]:0.0f;
        }
        const int grb=t*TILE+ty*FRAG;
        #pragma unroll
        for (int dy=0; dy<FRAG; ++dy) {
            const int br=grb+dy;
            #pragma unroll
            for (int dx=0; dx<FRAG; ++dx)
                Bs[ty*FRAG+dy][sc+dx]=(br<N&&col+dx<N)?B[br*N+col+dx]:0.0f;
        }
        __syncthreads();
        #pragma unroll
        for (int k=0; k<TILE; ++k) {
            a00+=As[ty*FRAG+0][k]*Bs[k][sc+0]; a01+=As[ty*FRAG+0][k]*Bs[k][sc+1];
            a02+=As[ty*FRAG+0][k]*Bs[k][sc+2]; a03+=As[ty*FRAG+0][k]*Bs[k][sc+3];
            a10+=As[ty*FRAG+1][k]*Bs[k][sc+0]; a11+=As[ty*FRAG+1][k]*Bs[k][sc+1];
            a12+=As[ty*FRAG+1][k]*Bs[k][sc+2]; a13+=As[ty*FRAG+1][k]*Bs[k][sc+3];
            a20+=As[ty*FRAG+2][k]*Bs[k][sc+0]; a21+=As[ty*FRAG+2][k]*Bs[k][sc+1];
            a22+=As[ty*FRAG+2][k]*Bs[k][sc+2]; a23+=As[ty*FRAG+2][k]*Bs[k][sc+3];
            a30+=As[ty*FRAG+3][k]*Bs[k][sc+0]; a31+=As[ty*FRAG+3][k]*Bs[k][sc+1];
            a32+=As[ty*FRAG+3][k]*Bs[k][sc+2]; a33+=As[ty*FRAG+3][k]*Bs[k][sc+3];
        }
        __syncthreads();
    }
    const int r0=row, c0=col;
    if (r0+0<N&&c0+0<N) C[r0*N+c0]=a00; if (r0+0<N&&c0+1<N) C[r0*N+c0+1]=a01;
    if (r0+0<N&&c0+2<N) C[r0*N+c0+2]=a02; if (r0+0<N&&c0+3<N) C[r0*N+c0+3]=a03;
    if (r0+1<N&&c0+0<N) C[(r0+1)*N+c0]=a10; if (r0+1<N&&c0+1<N) C[(r0+1)*N+c0+1]=a11;
    if (r0+1<N&&c0+2<N) C[(r0+1)*N+c0+2]=a12; if (r0+1<N&&c0+3<N) C[(r0+1)*N+c0+3]=a13;
    if (r0+2<N&&c0+0<N) C[(r0+2)*N+c0]=a20; if (r0+2<N&&c0+1<N) C[(r0+2)*N+c0+1]=a21;
    if (r0+2<N&&c0+2<N) C[(r0+2)*N+c0+2]=a22; if (r0+2<N&&c0+3<N) C[(r0+2)*N+c0+3]=a23;
    if (r0+3<N&&c0+0<N) C[(r0+3)*N+c0]=a30; if (r0+3<N&&c0+1<N) C[(r0+3)*N+c0+1]=a31;
    if (r0+3<N&&c0+2<N) C[(r0+3)*N+c0+2]=a32; if (r0+3<N&&c0+3<N) C[(r0+3)*N+c0+3]=a33;
}

