{"command":"cd /problem

# Benchmark several TILE/FRAG combinations
results=""

for TILE_FRAG in "64:4" "48:3" "32:2" "128:4" "96:6" "64:8"; do
    TILE=$(echo $TILE_FRAG | cut -d: -f1)
    FRAG=$(echo $TILE_FRAG | cut -d: -f2)
    BTIL=$(($TILE / $FRAG))
    THREADS=$(($BTIL * $BTIL))
    REGS_EST=$((16 + 8 * $FRAG * $FRAG))

    if [ $THREADS -gt 1024 ] || [ $REGS_EST -gt 120 ]; then
        echo "SKIP TILE=$TILE FRAG=$FRAG (THREADS=$THREADS REGS_EST=$REGS_EST)"
        continue
    fi

    # Check if TILE is divisible by FRAG
    if [ $(($TILE % $FRAG)) -ne 0 ]; then
        echo "SKIP TILE=$TILE FRAG=$FRAG (not divisible)"
        continue
    fi

    # Generate kernel
    cat > src/gemm.cu << KERNEL
#include "gemm.cuh"
#include <cuda_runtime.h>
#define TILE $TILE
#define FRAG $FRAG

__global__ void gemmKernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int N) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];
    const int numTiles = (N + TILE - 1) / TILE;
    const int ty = threadIdx.y, tx = threadIdx.x;
    const int row = blockIdx.y * TILE + ty * FRAG;
    const int col = blockIdx.x * TILE + tx * FRAG;
KERNEL

    # Generate accumulator declarations
    for i in $(seq 0 $(($FRAG-1))); do
        for j in $(seq 0 $(($FRAG-1))); do
            printf "    float acc_%d_%d=0;" $i $j
        done
        printf "\n"
    done >> src/gemm.cu

    # Main loop
    cat >> src/gemm.cu << 'LOOP'
    for (int t = 0; t < numTiles; ++t) {
        const int sc = tx * FRAG, gc = t * TILE + sc;
LOOP

    # Load A
    cat >> src/gemm.cu << 'LOADA'
        #pragma unroll
        for (int dy=0; dy<FRAG; ++dy) {
            const int ar=row+dy;
            #pragma unroll
            for (int dx=0; dx<FRAG; ++dx)
                As[ty*FRAG+dy][sc+dx]=(ar<N&&gc+dx<N)?A[ar*N+gc+dx]:0.0f;
        }
LOADA

    # Load B
    cat >> src/gemm.cu << 'LOADB'
        const int grb=t*TILE+ty*FRAG;
        #pragma unroll
        for (int dy=0; dy<FRAG; ++dy) {
            const int br=grb+dy;
            #pragma unroll
            for (int dx=0; dx<FRAG; ++dx)
                Bs[ty*FRAG+dy][sc+dx]=(br<N&&col+dx<N)?B[br*N+col+dx]:0.0f;
        }
LOADB

    cat >> src/gemm.cu << 'SYNC1'
        __syncthreads();
SYNC1

    # Compute
    cat >> src/gemm.cu << 'COMPUTE'
        #pragma unroll
        for (int k=0; k<TILE; ++k) {
COMPUTE

    for i in $(seq 0 $(($FRAG-1))); do
        for j in $(seq 0 $(($FRAG-1))); do
            printf "            acc_%d_%d+=As[ty*FRAG+%d][k]*Bs[k][sc+%d];\n" $i $j $i $j
        done
    done >> src/gemm.cu

    cat >> src/gemm.cu << 'SYNC2'
        }
        __syncthreads();
    }
SYNC2

    # Store
    printf "    const int r0=row, c0=col;\n" >> src/gemm.cu
    for i in $(seq 0 $(($FRAG-1))); do
        for j in $(seq 0 $(($FRAG-1))); do
            printf "    if (r0+%d<N&&c0+%d<N) C[(r0+%d)*N+(c0+%d)]=acc_%d_%d;\n" $i $j $i $j $i $j
        done
    done >> src/gemm.cu

    cat >> src/gemm.cu << 'ENDF'
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    if (N<=0) return;
    dim3 block(TILE/FRAG, TILE/FRAG);
    dim3 grid((N+TILE-1)/TILE, (N+TILE-1)/TILE);
    gemmKernel<<<grid,block>>>(dA, dB, dC, N);
}
ENDF

    # Build and test
    make clean >/dev/null 2>&1
    result=$(make ARCH="-arch=sm_86" 2>&1)
    if echo "$result" | grep -q "error"; then
        echo "TILE=$TILE FRAG=$FRAG: COMPILE ERROR"
        continue
    fi

    perf=$(./gemm -c 2>&1 | grep "Performance:" | grep -oP '[0-9.]+(?= GFLOP)')
    mse=$(./gemm -c 2>&1 | grep "Mean Squared Error" | awk '{print $4}')

    echo "TILE=$TILE FRAG=$FRAG THREADS=$THREADS PERF=$perf GFLOP MSE=$mse"

    sleep 2
done","timeout":120}

