{"content":"#include "gemm.cuh"

#include <cuda_runtime.h>
#include <mma.h>
using namespace nvcuda;

// ============================================================================
// Tensor-core tiled GEMM: C = A * B for NxN row-major FP32 matrices.
//
// Strategy: accumulate partial products in FP32 by doing wmma FP16→FP32
// multiply for 16x16 sub-tiles, then summing results in FP32.
// To keep FP32 precision, each 16-wide inner dimension is summed in FP32.
//
// Architecture: TILE=64, processed as 4×4=16 wmma tiles.
// Block: 1 warp group (4 warp groups of 4 warps each = 16 warps = 512 threads).
// Each warp group computes a 16x16 sub-tile of the output.
// ============================================================================

#define TILE 64
#define MMA_SIZE 16
#define WG_SIZE 4  // warp groups per tile dimension

// FP16 wmma fragment types
#define WMMA_M 16
#define WMMA_N 16
#define WMMA_K 16

using matA = wmma::fragment<wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K, half, wmma::row_major>;
using matB = wmma::fragment<wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K, half, wmma::col_major>;
using accF = wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float>;

// Shared memory: 2 * TILE * TILE * 2 bytes for FP16 A and B tiles
#define SMA_SIZE (TILE * TILE * 2 * sizeof(half))

__constant__ half dA_smem[SMA_SIZE / sizeof(half)];
__constant__ half dB_smem[SMA_SIZE / sizeof(half)];

__global__ void gemmKernel(const float* __restrict__ dA,
                           const float* __restrict__ dB,
                           float* __restrict__ dC,
                           int N) {
    // Shared memory for FP16 tile data
    // We use a single large shared memory area that all warps share
    extern __shared__ char smem[];
    half* __restrict__ sA = reinterpret_cast<half*>(smem);
    half* __restrict__ sB = sA + TILE * TILE;

    const int numTiles = (N + TILE - 1) / TILE;
    const int warpId = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;

    // Warp group: (wgRow, wgCol) where each processes a 16x16 sub-tile
    const int wgRow = warpId / WG_SIZE;
    const int wgCol = warpId % WG_SIZE;

    // Global output position for this warp group
    const int outRow = blockIdx.y * TILE + wgRow * WMMA_SIZE;
    const int outCol = blockIdx.x * TILE + wgCol * WMMA_SIZE;

    // Initialize FP32 accumulator (4 wmma fragments = 16x16 output)
    accF accum[WG_SIZE];  // one per column-warp-group
    for (int j = 0; j < WG_SIZE; ++j) {
        wmma::fill_fragment(accum[j], 0.0f);
    }

    for (int t = 0; t < numTiles; ++t) {
        const int tileRow = t * TILE;
        const int tileCol = t * TILE;

        // All 16 warps cooperatively load the A and B tiles into shared memory.
        // Thread maps to (row_in_tile, col_in_tile):
        //   row_in_tile = lane (0..31), col_in_tile = warpId * 2 + (lane / 16) (0..15)
        // Each thread loads 2 elements from A (row-major) and 2 from B.

        // Load A tile: threads handle wgRow * 16 rows of the tile
        {
            const int ar = outRow;  // tile row start
            const int br = tileCol; // tile col start (for B, it's row)
            const int n = N;
            const int a_stride = n;

            // Each warp group (wgRow) handles 16 rows: [wgRow*16 .. +15]
            // Thread in warp: lane 0..31 → row offset 0..15 (lane/2), col offset 0..31
            // Wait, that's 32 elements but we need to cover 16 rows × 64 cols.
            // Let me reconsider: each warp loads 64 elements (2 rows × 32 cols, since 2 elements/row).
            // Actually: each thread loads 2 elements from A tile. 512 threads × 2 = 1024 = 16*64. ✓

            // Thread idx → row in 64×64 tile = lane (0..31), col in tile = warpId
            // But warpId goes 0..15, and lane 0..31. That gives us row=lane, col=warpId.
            // But we need to load from GLOBAL memory, not shared.

            // Each thread loads A tile[wgRow*16+lane/2][tileCol + warpId*2 + lane%2]
            // = A[(tileRow + wgRow*16 + lane/2)*N + tileCol + warpId*2 + lane%2]
            const int myTileRow = wgRow * WMMA_SIZE + lane / 2;  // 0..63
            const int myTileCol = warpId * 2 + lane % 2;          // 0..31... wait that's wrong
            // warpId goes 0..15, so warpId*2+lane%2 = 0..31. But we need 0..63.
            // Let me recalculate. 512 threads, 64*64=4096 elements. Each thread loads 2.
            // threadIdx.x = 0..511.
            // row = threadIdx.x % TILE = threadIdx.x % 64. This gives 0..511, cycling 0..63.
            // col = threadIdx.x / TILE = threadIdx.x / 64. This gives 0..7. Only 8 columns!
            // 512*2 = 1024 elements, but 64*64 = 4096. We're missing 3072 elements.
            // 512 threads × 2 = 1024 ≠ 4096. Each thread needs to load 8 elements (4096/512=8).
        }

        // Let me rethink. 512 threads, 4096 elements. Each thread loads 8 elements = 4 half = 8 bytes.
        // Using int4 loads: 4096*2 bytes / (512*16 bytes per int4) = 4096*2/8192 = 1. So each thread
        // loads 1 int4 = 4 half values. 512 int4 = 2048 half values. Still only half!
        // Each thread needs to load 2 int4 = 8 half values.

        // Actually: 512 threads × 2 int4 × 4 half/int4 = 4096 half. ✓

