#include <cuda_runtime.h>
#include <mma.h>
using namespace nvcuda;

// ============================================================================
// Tensor-core tiled GEMM: C = A * B for NxN row-major FP32 matrices.
// Uses wmma FP16->FP32 with FP32 accumulation.
// TILE=64, 16 warp groups (16 warps = 512 threads).
// Each warp group computes one 16x16 sub-tile of the 64x64 output.
// ============================================================================

#define TILE 64
#define MMA_SIZE 16
#define WG_SIZE 4  // warp groups per tile dimension
#define TOTAL_WARPS (WG_SIZE * WG_SIZE)  // 16

// Shared memory layout: FP16 tiles
// sA[wgRow * TILE][TILE] for wgRow in [0..WG_SIZE-1]
// sB[wgCol * TILE][TILE] for wgCol in [0..WG_SIZE-1]
// But actually, all warps need to share the SAME 64x64 tile.
// So we use a single sA[TILE][TILE] and sB[TILE][TILE] in shared memory.
// Total: 2 * 64 * 64 * 2 bytes = 16384 bytes.

#define SMA_BYTES (2 * TILE * TILE * sizeof(half))

// FP16 wmma fragment types
using matA = wmma::fragment<wmma::matrix_a, MMA_SIZE, MMA_SIZE, MMA_SIZE, half, wmma::row_major>;
using matB = wmma::fragment<wmma::matrix_b, MMA_SIZE, MMA_SIZE, MMA_SIZE, half, wmma::col_major>;
using accC = wmma::fragment<wmma::accumulator, MMA_SIZE, MMA_SIZE, MMA_SIZE, float>;

__global__ void gemmKernel(const float* __restrict__ dA,
                           const float* __restrict__ dB,
                           float* __restrict__ dC,
                           int N) {
    extern __shared__ char smem[];
    half* __restrict__ sA = reinterpret_cast<half*>(smem);
    half* __restrict__ sB = sA + TILE * TILE;

    const int numTiles = (N + TILE - 1) / TILE;
    const int warpId = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;

    const int wgRow = warpId / WG_SIZE;
    const int wgCol = warpId % WG_SIZE;

    // Global output position for this warp group
    const int outRow = blockIdx.y * TILE + wgRow * MMA_SIZE;
    const int outCol = blockIdx.x * TILE + wgCol * MMA_SIZE;

    // Accumulator: one accC per column warp-group (4 total)
    accC accum[WG_SIZE];
    for (int j = 0; j < WG_SIZE; ++j) {
        wmma::fill_fragment(accum[j], 0.0f);
    }

    for (int t = 0; t < numTiles; ++t) {
        const int tileStart = t * TILE;

        // Cooperative load: all 16 warps load the 64x64 A and B tiles
        // Each thread loads 2 half values from A and 2 from B
        // Thread maps to (row_in_tile, col_in_tile):
        //   row = lane, col = warpId  (since 512 threads = 32 lanes × 16 warps)
        // Each thread loads 2 elements = 4 half values total (2 from A, 2 from B)

        // Actually, each thread needs to handle:
        // 64×64 elements / 512 threads = 8 elements per thread
        // But we need to load A (64×64) and B (64×64) = 8192 half values
        // 8192 / 512 = 16 half values per thread

        // Let me use: each thread loads 4 half from A and 4 from B (8 float → 8 half conversion)

        const int ar = tileStart + lane;  // row in global A
        const int br = tileStart + lane;  // row in global B
        const int ac = tileStart + warpId * 2;  // col in global A
        const int bc = tileStart + warpId * 2;  // col in global B

        // Load A: 4 consecutive elements starting at (ar, ac) in the tile
        // Global A: A[ar * N + ac + k] for k = 0..3
        if (ar < N) {
            for (int k = 0; k < 4; ++k) {
                int gc = ac + k;
                if (gc < N) {
                    half h = __float2half(dA[ar * N + gc]);
                    // Store to shared memory at wmma layout position
                    // wmma expects row-major: sA[(wgRow * 16 + lane / 2) * 64 + warpId * 2 + lane % 2]
                    // Actually, let's use simple row-major layout for now
                    sA[lane * 8 + warpId * 2 + (k < 2 ? 0 : 1)] = h;
                }
            }
        }

        // Load B: similar
        if (br < N) {
            for (int k = 0; k < 4; ++k) {
                int gc = bc + k;
                if (gc < N) {
                    half h = __float2half(dB[br * N + gc]);
                    sB[lane * 8 + warpId * 2 + (k < 2 ? 0 : 1)] = h;
                }
            }
        }

        __syncthreads();

        // Load wmma fragments from shared memory
        // Each warp group loads its 16x16 sub-tile of A and B
        matA a_frag[WG_SIZE];
        matB b_frag[WG_SIZE];

        for (int i = 0; i < WG_SIZE; ++i) {
            wmma::load_matrix_sync(a_frag[i], sA + (wgRow * MMA_SIZE + i * MMA_SIZE) * TILE + MMA_SIZE * i, TILE, wmma::mem_row_major);
            wmma::load_matrix_sync(b_frag[i], sB + (i * MMA_SIZE) * TILE + wgCol * MMA_SIZE, TILE, wmma::mem_col_major);
        }

        // Matrix multiply: accum += a_frag[i] * b_frag[j] for i,j in [0..WG_SIZE-1]
        for (int i = 0; i < WG_SIZE; ++i) {
            for (int j = 0; j < WG_SIZE; ++j) {
                wmma::mma_sync(accum[j], a_frag[i], b_frag[j], accum[j]);
            }
        }

        __syncthreads();
    }

    // Store output: each warp group stores its 16x16 result to global memory
    for (int j = 0; j < WG_SIZE; ++j) {
        float* c_ptr = dC + (outRow) * N + (outCol + j * MMA_SIZE);
        wmma::store_matrix_sync(c_ptr, accum[j], N, wmma::mem_row_major);
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    if (N <= 0) return;
    dim3 block(512);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block, SMA_BYTES>>>(dA, dB, dC, N);
}
