using namespace nvcuda;

// ============================================================================
// Tensor-core tiled GEMM: C = A * B for NxN row-major FP32 matrices.
// Uses wmma FP16×FP16→FP32 multiply-accumulate.
//
// Tile size: 64×64, processed as 4×4=16 wmma sub-tiles.
// Block: 16 warps (512 threads). Each warp handles one 16×16 sub-tile.
// Shared memory: 2 × 64 × 64 half = 16 KB (for FP16 A and B tiles).
// ============================================================================

#define TILE 64
#define MMA 16
#define WGRP 4  // warp groups per tile dimension (4×4=16 warps total)
#define SBYTES (2 * TILE * TILE * sizeof(half))

using matA = wmma::fragment<wmma::matrix_a, MMA, MMA, MMA, half, wmma::row_major>;
using matB = wmma::fragment<wmma::matrix_b, MMA, MMA, MMA, half, wmma::col_major>;
using accC = wmma::fragment<wmma::accumulator, MMA, MMA, MMA, float>;

__global__ void gemmKernel(const float* __restrict__ dA,
                           const float* __restrict__ dB,
                           float* __restrict__ dC,
                           int N) {
    extern __shared__ char smem[];
    half* __restrict__ sA = reinterpret_cast<half*>(smem);
    half* __restrict__ sB = sA + TILE * TILE;

    const int numTiles = (N + TILE - 1) / TILE;
    const int warpId = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;

    // Warp-group coordinates
    const int wgRow = warpId / WGRP;  // 0..3
    const int wgCol = warpId % WGRP;   // 0..3

    // Output position (top-left of 16×16 sub-tile)
    const int gRow = blockIdx.y * TILE + wgRow * MMA;
    const int gCol = blockIdx.x * TILE + wgCol * MMA;

    // 4 accumulators: one per column position
    accC accum[WGRP];
    #pragma unroll
    for (int j = 0; j < WGRP; ++j)
        wmma::fill_fragment(accum[j], 0.0f);

    // Inner dimension in matrix units: TILE = 64 = 4×MMA
    // For each k-step (w = 0..3):
    //   C += A[gRow:gRow+16][tile+w*MMA:tile+w*MMA+MMA] ×
    //         B[tile+w*MMA:tile+w*MMA+MMA][gCol:gCol+16]
    // There are 4 such k-steps per tile.

    for (int t = 0; t < numTiles; ++t) {
        const int ts = t * TILE;

        // -----------------------------------------------------------
        // 1) Cooperative global-load + convert FP32→FP16 → shared mem
        // -----------------------------------------------------------
        // Thread (warpId, lane) → (row_in_tile, col_in_tile) in the 64×64 tile:
        //   row_in_tile = lane                    (0..31)
        //   col_in_tile = warpId                  (0..15)
        // Each thread loads 8 half values from A and 8 from B (16×8=128 per matrix,
        // but actually we need 64×64=4096 per matrix, 4096/512=8 per thread).
        //
        // Row in global: ts + lane
        // Col in global: ts + warpId
        // Each thread loads 8 consecutive elements: col = ts+warpId .. ts+warpId+7
        // But consecutive in a row → not coalesced (stride = N).
        //
        // Better layout: row = warpId, col = lane.
        //   Row in global: ts + warpId (0..15)
        //   Col in global: ts + lane   (0..31)
        // Each thread loads: A[(ts+warpId)*N + ts+lane + k*32] for k=0,1
        // That gives row-stride access, which is NOT coalesced.
        //
        // Best coalesced load: contiguous warps (same warpId, consecutive lane)
        //   → consecutive elements in global memory → coalesced.
        // Thread (warpId, lane) loads A[(ts+lane)*N + ts+warpId*2 + 0..1]
        // This is: 2 consecutive elements per thread → 2*32*2 = 2048 bytes per warp
        // per load. 2 loads (A and B).
        // Total elements loaded: 512 threads × 2 (rows) × 2 (elements per thread)
        //   = 2048 elements × 2 matrices = 4096 half per matrix = 64×64. ✓

        // Cooperative load of A tile
        // Thread maps: row_in_tile = lane, col_in_tile = warpId
        // Loads 2 elements starting at [lane][warpId*2 + k] in the tile
        // Global: (ts + lane) * N + ts + warpId*2 + k

        const int tileRowA = ts + lane;
        const int tileColA = ts + warpId * 2;
        const int strideA = N;

        if (tileRowA < N) {
            const float* __restrict__ a0 = dA + tileRowA * strideA + tileColA;
            const float* __restrict__ a1 = a0 + 2;
            // Store to shared memory: row-major sA[row*64+col]
            // Thread stores at: lane*64 + warpId*2 + 0, lane*64 + warpId*2 + 1
            // Wait, but we need to be careful about bank conflicts and coalescing.
            // Shared memory is word-addressable (32-bit = 4-byte words).
            // With 32 threads per warp, 64 columns → 2 words per row.
            // Row lane: threads 0-31, columns 0-63. Each thread handles 2 columns.
            // Col 0→thread 0, col 1→thread 0, col 2→thread 1, etc.
            // Thread i loads columns 2i, 2i+1 → word address 2i/2 = i. Coalesced! ✓

