            sA[lane * TILE + warpId * 2 + 3] = __float2half(a1[1]);
            sA[lane * TILE + warpId * 2 + 4] = __float2half(a0[4]);
            sA[lane * TILE + warpId * 2 + 5] = __float2half(a0[5]);
            sA[lane * TILE + warpId * 2 + 6] = __float2half(a1[4]);
            sA[lane * TILE + warpId * 2 + 7] = __float2half(a1[4]);
