        // No wait, 64×64=4096 half per matrix. 512 threads → 8 per thread.

        // Let me just do the straightforward thing:
        // Thread (lane, warpId) loads:
        //   A[(ts+lane)*N + ts+warpId + 0..7] = 8 consecutive half values
        //   B[(ts+lane)*N + ts+warpId + 0..7] = 8 consecutive half values
        // Global stride = N (usually large), so 8 consecutive in a row IS coalesced.
        // But lane maps 0-31, and warpId maps 0-15. 32*16 = 512. ✓

        // Hmm but warpId*8 could go up to 15*8 = 120 which exceeds tile width 64.
        // So warpId should go 0..7 for 8 columns, and lane 0..63 for 64 rows.
        // But we only have 512 threads = 16 warps × 32 lanes.
        // 16 warps → warpId 0..15. 32 lanes → lane 0..31.
        // For row-major tiles: we need 64 rows and 64 cols.
        // Thread 0..511 → row = (threadIdx.x % 64), col = threadIdx.x / 64.
        // But threadIdx.x = warpId*32 + lane. So threadIdx.x % 64 = (warpId*32+lane)%64.
        // For warpId=0: lane 0..31 → row 0..31
        // For warpId=1: lane 0..31 → row 32..63
        // threadIdx.x / 64 = warpId*32+lane / 64.
        // For warpId=0: (0*32+lane)/64 = 0 for all lane → col 0
        // For warpId=1: (32+lane)/64 = 0 for lane 0..31 → col 0
        // For warpId=2: (64+lane)/64 = 1 for all lane → col 1
        // That gives: warpId 0,1 → col 0; warpId 2,3 → col 1; etc.
        // That means threads 0-63 (warpId 0,1) all have col 0.
        // That's only 8 columns for 512 threads → each thread handles 8 elements.

        // Let me just do it with explicit thread indexing:
        // threadIdx.x → (r, c) in the 64×64 tile:
        //   r = threadIdx.x % 64
        //   c = threadIdx.x / 64
        // But threadIdx.x goes 0..511. r=0..63, c=0..7.
        // 8 cols × 64 rows = 512 positions = 512 threads. ✓
        // Each thread handles 1 element from A and 1 from B per tile load.
        // We have 2 tiles (A and B) per k-step. But actually, the entire 64×64
        // tile is loaded once per outer tile iteration (numTiles).
        // So each thread loads 2 half values per numTiles iteration.

        // But wait, we need 8 half per thread (4096/512). So each thread needs
        // to load 8 from A and 8 from B. 16 total.
        // If each thread loads 1 element per tile and we have 4 k-steps per tile
        // (since TILE=64 and each k-step processes MMA=16 elements), then:
        // 4 k-steps × 1 element = 4 elements. That's not enough (need 8).

        // OK, let me restructure. The shared memory holds the full 64×64 tile.
        // Each thread (threadIdx.x) handles position (r, c) where:
        //   r = threadIdx.x % 64, c = threadIdx.x / 64
        // Thread loads: sA[r*64 + c] = A[(ts+r)*N + ts+c] (converted to half)
        //               sB[r*64 + c] = B[(ts+r)*N + ts+c] (converted to half)
        // That's 1 element each, 512 threads → 512 of 4096 covered.
        // We need 4096/512 = 8 per thread.

        // Simplest: each thread loads 8 elements.
        // Thread x loads elements at r, c where:
        //   r = (x * 8) % 64, c = (x * 8) / 64
        // Hmm that doesn't work either since x*8 can exceed 4096.

        // Let me use: each thread loads 8 consecutive elements from row-major order
        // Thread x: offset = x * 8
        //   r = offset / 64, c = offset % 64
        //   → A[(ts+r)*N + ts+c] for c, c+1, ..., c+7 (wrapping)

        // But 64 is not divisible by 8 for the wrapping...
        // Let me just load 8 elements in a row:
        //   Thread x: row = (x % 64), start_col = (x / 64) * 8
        //   loads: A[(ts+row)*N + ts+start_col .. ts+start_col+7]
        // row ∈ [0,63], start_col ∈ {0,8,16,...,56} for x/64 ∈ {0,1,...,7}
        // Each thread loads 8 elements → 512*8=4096. ✓
        // Col start goes 0,8,...,56 → 8 per row. 8 rows per warp. 2 warps per tile row.
        // Total: 4 tile rows × 8 rows × 32 threads = 1024... that's wrong.

        // I'm overcomplicating this. Let me just use a simple mapping:
        // Each thread (id=0..511) loads 8 consecutive half values from the
        // 64×64 tile in row-major order.
        // element_index = id * 8 + k, for k = 0..7
        // tile_row = element_index / 64, tile_col = element_index % 64
        // Global: A[(ts + tile_row) * N + ts + tile_col]

        // For coalescing: consecutive thread IDs (same warp) load consecutive elements.
        // Thread id: warpId*32+lane, element_start = (warpId*32+lane)*8
        // For lane=0,1,...,31: element_start = 0,8,16,...,248 (in row-major of tile)
        // tile_row for lane=0: 0/64=0, tile_col=0%64=0
        // tile_row for lane=4: 32/64=0, tile_col=32%64=32
        // tile_row for lane=7: 56/64=0, tile_col=56%64=56
        // tile_row for lane=8: 64/64=1, tile_col=0%64=0
        // So threads 0-7 cover tile rows 0-0, then thread 8 covers row 1.
        // Consecutive elements 0-7 all in row 0 → coalesced global load from row 0. ✓
        // Consecutive elements 8-15: thread 1 loads elements 8-15. All in row 0.
        // Actually, consecutive THREADS access consecutive ELEMENTS in tile row-major order,
        // which is consecutive in global memory → coalesced! ✓

        // So the mapping is:
        //   Thread x, element k (0..7):
        //     elem = x*8 + k
        //     r = elem / 64
        //     c = elem % 64
        //     sA[r*64 + c] = __float2half(dA[(ts+r)*N + ts+c])

        // But we need to also handle boundary conditions for non-tile-aligned N.

        for (int e = 0; e < 8; ++e) {
            int elem = threadIdx.x * 8 + e;
            if (elem < TILE * TILE) {
                int r = elem / TILE;
                int c = elem % TILE;
                int gr = ts + r;
                int gc = ts + c;
                if (gr < N && gc < N) {
                    sA[r * TILE + c] = __float2half(dA[gr * N + gc]);
                    sB[r * TILE + c] = __float2half(dB[gr * N + gc]);
                }
            }
        }

        __syncthreads();

        // -----------------------------------------------------------
        // 2) Load wmma fragments from shared memory
        // -----------------------------------------------------------
        // 4 wmma steps (k-index 0..3)
        // For warp group (wgRow, wgCol):
        //   A fragments: rows [wgRow*MMA .. +15], cols [w*MMA .. +15] for w=0..3
        //   B fragments: rows [w*MMA .. +15], cols [wgCol*MMA .. +15] for w=0..3
        matA a_frag[WGRP];
        matB b_frag[WGRP];
        #pragma unroll
        for (int w = 0; w < WGRP; ++w) {
            wmma::load_matrix_sync(a_frag[w], sA + (wgRow * MMA + w * MMA) * TILE + MMA * 0, TILE, wmma::mem_row_major);
            wmma::load_matrix_sync(b_frag[w], sB + (w * MMA) * TILE + wgCol * MMA, TILE, wmma::mem_col_major);
        }

        // -----------------------------------------------------------
        // 3) wmma multiply-accumulate
        // -----------------------------------------------------------
        #pragma unroll
        for (int w = 0; w < WGRP; ++w) {
            #pragma unroll
            for (int j = 0; j < WGRP; ++j) {
                wmma::mma_sync(accum[j], a_frag[w], b_frag[j], accum[j]);
            }
        }

        __syncthreads();
    }

    // -----------------------------------------------------------
    // 4) Store 4 accumulators to global memory (FP32 output)
    // -----------------------------------------------------------
    #pragma unroll
    for (int j = 0; j < WGRP; ++j) {
        wmma::store_matrix_sync(dC + gRow * N + (gCol + j * MMA),
                                accum[j], N, wmma::mem_row_major);
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    if (N <= 0) return;
    dim3 block(512);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block, SBYTES>>>(dA, dB, dC, N);
}
