#include <cuda_runtime.h>
#include <mma.h>
using namespace nvcuda;

// Tile: 64x64, processed as 4x4=16 wmma sub-tiles (16x16 each).
// 16 warps (512 threads) per block. Each handles one 16x16 output sub-tile.
// Shared memory: FP16 tiles for A and B (16 KB each).

#define TILE 64
#define MMA 16
#define WGRP 4  // 4 warp groups per dimension → 16 warps total
#define SBYTES (2 * TILE * TILE * sizeof(half))

using matA = wmma::fragment<wmma::matrix_a, MMA, MMA, MMA, half, wmma::row_major>;
using matB = wmma::fragment<wmma::matrix_b, MMA, MMA, MMA, half, wmma::col_major>;
using accC = wmma::fragment<wmma::accumulator, MMA, MMA, MMA, float>;

__global__ void gemmKernel(const float* __restrict__ dA,
                           const float* __restrict__ dB,
                           float* __restrict__ dC,
                           int N) {
    extern __shared__ char smem[];
    half* __restrict__ sA = reinterpret_cast<half*>(smem);
    half* __restrict__ sB = sA + TILE * TILE;

    const int numTiles = (N + TILE - 1) / TILE;
    const int warpId = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;

    const int wgRow = warpId / WGRP;
    const int wgCol = warpId % WGRP;

    const int gRow = blockIdx.y * TILE + wgRow * MMA;
    const int gCol = blockIdx.x * TILE + wgCol * MMA;

    accC accum[WGRP];
    #pragma unroll
    for (int j = 0; j < WGRP; ++j)
        wmma::fill_fragment(accum[j], 0.0f);

    for (int t = 0; t < numTiles; ++t) {
        const int ts = t * TILE;

        // Cooperative load: each thread converts 8 FP32→FP16 values
        for (int e = 0; e < 8; ++e) {
            int elem = threadIdx.x * 8 + e;
            if (elem < TILE * TILE) {
                int r = elem / TILE;
                int c = elem % TILE;
                int gr = ts + r;
                int gc = ts + c;
                if (gr < N && gc < N) {
                    sA[r * TILE + c] = __float2half(dA[gr * N + gc]);
                    sB[r * TILE + c] = __float2half(dB[gr * N + gc]);
                }
            }
        }

        __syncthreads();

        // Load wmma fragments from shared memory
        matA a_frag[WGRP];
        matB b_frag[WGRP];
        #pragma unroll
        for (int w = 0; w < WGRP; ++w) {
            wmma::load_matrix_sync(a_frag[w], sA + (wgRow * MMA + w * MMA) * TILE, TILE, wmma::mem_row_major);
            wmma::load_matrix_sync(b_frag[w], sB + (w * MMA) * TILE + wgCol * MMA, TILE, wmma::mem_col_major);
        }

        // wmma multiply-accumulate
        #pragma unroll
        for (int w = 0; w < WGRP; ++w) {
            #pragma unroll
            for (int j = 0; j < WGRP; ++j) {
                wmma::mma_sync(accum[j], a_frag[w], b_frag[j], accum[j]);
            }
        }

        __syncthreads();
    }

    // Store 4 accumulators to global FP32 memory
    #pragma unroll
    for (int j = 0; j < WGRP; ++j) {
        wmma::store_matrix_sync(dC + gRow * N + (gCol + j * MMA),
                                accum[j], N, wmma::mem_row_major);
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    if (N <= 0) return;
    dim3 block(512);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block, SBYTES>>>(dA, dB, dC, N);
}
