{"content":"#include "gemm.cuh"

#include <cuda_runtime.h>

// Double-buffered tiled GEMM: TILE=64, FRAG=4, 256 threads/block.
// Overlaps next tile load with current tile compute.

#define TILE 64
#define FRAG 4

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    __shared__ float As[2][TILE][TILE];
    __shared__ float Bs[2][TILE][TILE];

    const int numTiles = (N + TILE - 1) / TILE;
    const int ty = threadIdx.y;
    const int tx = threadIdx.x;

    const int row = blockIdx.y * TILE + ty * FRAG;
    const int col = blockIdx.x * TILE + tx * FRAG;

    float a00 = 0.0f, a01 = 0.0f, a02 = 0.0f, a03 = 0.0f;
    float a10 = 0.0f, a11 = 0.0f, a12 = 0.0f, a13 = 0.0f;
    float a20 = 0.0f, a21 = 0.0f, a22 = 0.0f, a23 = 0.0f;
    float a30 = 0.0f, a31 = 0.0f, a32 = 0.0f, a33 = 0.0f;

    // Load tile 0
    {
        const int buf = 0;
        const int sc = tx * FRAG, gc = 0 * TILE + sc;
        #pragma unroll
        for (int dy = 0; dy < FRAG; ++dy) {
            const int ar = row + dy;
            #pragma unroll
            for (int dx = 0; dx < FRAG; ++dx)
                As[buf][ty * FRAG + dy][sc + dx] =
                    (ar < N && gc + dx < N) ? A[ar * N + gc + dx] : 0.0f;
        }
        const int grb = 0 * TILE + ty * FRAG;
        #pragma unroll
        for (int dy = 0; dy < FRAG; ++dy) {
            const int br = grb + dy;
            #pragma unroll
            for (int dx = 0; dx < FRAG; ++dx)
                Bs[buf][ty * FRAG + dy][sc + dx] =
                    (br < N && col + dx < N) ? B[br * N + col + dx] : 0.0f;
        }
        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            a00 += As[buf][ty * FRAG + 0][k] * Bs[buf][k][sc + 0];
            a01 += As[buf][ty * FRAG + 0][k] * Bs[buf][k][sc + 1];
            a02 += As[buf][ty * FRAG + 0][k] * Bs[buf][k][sc + 2];
            a03 += As[buf][ty * FRAG + 0][k] * Bs[buf][k][sc + 3];
            a10 += As[buf][ty * FRAG + 1][k] * Bs[buf][k][sc + 0];
            a11 += As[buf][ty * FRAG + 1][k] * Bs[buf][k][sc + 1];
            a12 += As[buf][ty * FRAG + 1][k] * Bs[buf][k][sc + 2];
            a13 += As[buf][ty * FRAG + 1][k] * Bs[buf][k][sc + 3];
            a20 += As[buf][ty * FRAG + 2][k] * Bs[buf][k][sc + 0];
            a21 += As[buf][ty * FRAG + 2][k] * Bs[buf][k][sc + 1];
            a22 += As[buf][ty * FRAG + 2][k] * Bs[buf][k][sc + 2];
            a23 += As[buf][ty * FRAG + 2][k] * Bs[buf][k][sc + 3];
            a30 += As[buf][ty * FRAG + 3][k] * Bs[buf][k][sc + 0];
            a31 += As[buf][ty * FRAG + 3][k] * Bs[buf][k][sc + 1];
            a32 += As[buf][ty * FRAG + 3][k] * Bs[buf][k][sc + 2];
            a33 += As[buf][ty * FRAG + 3][k] * Bs[buf][k][sc + 3];
        }
    }

    for (int t = 1; t < numTiles; ++t) {
        const int buf = t & 1;
        const int sc = tx * FRAG;
        const int gc = t * TILE + sc;

        // Load next tile while previous is being used
        #pragma unroll
        for (int dy = 0; dy < FRAG; ++dy) {
            const int ar = row + dy;
            #pragma unroll
            for (int dx = 0; dx < FRAG; ++dx)
                As[buf][ty * FRAG + dy][sc + dx] =
                    (ar < N && gc + dx < N) ? A[ar * N + gc + dx] : 0.0f;
        }
        const int grb = t * TILE + ty * FRAG;
        #pragma unroll
        for (int dy = 0; dy < FRAG; ++dy) {
            const int br = grb + dy;
            #pragma unroll
            for (int dx = 0; dx < FRAG; ++dx)
                Bs[buf][ty * FRAG + dy][sc + dx] =
                    (br < N && col + dx < N) ? B[br * N + col + dx] : 0.0f;
        }

        int prev = 1 - buf;
        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            a00 += As[prev][ty * FRAG + 0][k] * Bs[prev][k][sc + 0];
            a01 += As[prev][ty * FRAG + 0][k] * Bs[prev][k][sc + 1];
            a02 += As[prev][ty * FRAG + 0][k] * Bs[prev][k][sc + 2];
            a03 += As[prev][ty * FRAG + 0][k] * Bs[prev][k][sc + 3];
            a10 += As[prev][ty * FRAG + 1][k] * Bs[prev][k][sc + 0];
            a11 += As[prev][ty * FRAG + 1][k] * Bs[prev][k][sc + 1];
            a12 += As[prev][ty * FRAG + 1][k] * Bs[prev][k][sc + 2];
            a13 += As[prev][ty * FRAG + 1][k] * Bs[prev][k][sc + 3];
            a20 += As[prev][ty * FRAG + 2][k] * Bs[prev][k][sc + 0];
            a21 += As[prev][ty * FRAG + 2][k] * Bs[prev][k][sc + 1];
            a22 += As[prev][ty * FRAG + 2][k] * Bs[prev][k][sc + 2];
            a23 += As[prev][ty * FRAG + 2][k] * Bs[prev][k][sc + 3];
            a30 += As[prev][ty * FRAG + 3][k] * Bs[prev][k][sc + 0];
            a31 += As[prev][ty * FRAG + 3][k] * Bs[prev][k][sc + 1];
            a32 += As[prev][ty * FRAG + 3][k] * Bs[prev][k][sc + 2];
            a33 += As[prev][ty * FRAG + 3][k] * Bs[prev][k][sc + 3];
        }

        __syncthreads();
    }

