{"content":"#include "gemm.cuh"

#include <cuda_runtime.h>

// Tiled single-precision GEMM optimized for Ampere (sm_86/A40).
// TILE=64 shared-memory tile with FRAG=4 register-tiled 4x4 output blocks
// per thread. Block: 16x16=256 threads (8 warps).

#define TILE 64
#define FRAG 4

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    const int numTiles = (N + TILE - 1) / TILE;
    const int ty = threadIdx.y;
    const int tx = threadIdx.x;

    const int row = blockIdx.y * TILE + ty * FRAG;
    const int col = blockIdx.x * TILE + tx * FRAG;

    float a00 = 0.0f, a01 = 0.0f, a02 = 0.0f, a03 = 0.0f;
    float a10 = 0.0f, a11 = 0.0f, a12 = 0.0f, a13 = 0.0f;
    float a20 = 0.0f, a21 = 0.0f, a22 = 0.0f, a23 = 0.0f;
    float a30 = 0.0f, a31 = 0.0f, a32 = 0.0f, a33 = 0.0f;

    for (int t = 0; t < numTiles; ++t) {
        const int sc = tx * FRAG;
        const int gc = t * TILE + sc;

        // --- Load A tile (coalesced global loads, row-major) ---
        #pragma unroll
        for (int dy = 0; dy < FRAG; ++dy) {
            const int ar = row + dy;
            #pragma unroll
            for (int dx = 0; dx < FRAG; ++dx) {
                As[ty * FRAG + dy][sc + dx] =
                    (ar < N && gc + dx < N) ? A[ar * N + gc + dx] : 0.0f;
            }
        }

        // --- Load B tile (coalesced global loads) ---
        const int grb = t * TILE + ty * FRAG;
        #pragma unroll
        for (int dy = 0; dy < FRAG; ++dy) {
            const int br = grb + dy;
            #pragma unroll
            for (int dx = 0; dx < FRAG; ++dx) {
                Bs[ty * FRAG + dy][sc + dx] =
                    (br < N && col + dx < N) ? B[br * N + col + dx] : 0.0f;
            }
        }

        __syncthreads();

        // --- Compute: 4x4 = 16 independent FMAs per k-iteration ---
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            a00 += As[ty * FRAG + 0][k] * Bs[k][sc + 0];
            a01 += As[ty * FRAG + 0][k] * Bs[k][sc + 1];
            a02 += As[ty * FRAG + 0][k] * Bs[k][sc + 2];
            a03 += As[ty * FRAG + 0][k] * Bs[k][sc + 3];
            a10 += As[ty * FRAG + 1][k] * Bs[k][sc + 0];
            a11 += As[ty * FRAG + 1][k] * Bs[k][sc + 1];
            a12 += As[ty * FRAG + 1][k] * Bs[k][sc + 2];
            a13 += As[ty * FRAG + 1][k] * Bs[k][sc + 3];
            a20 += As[ty * FRAG + 2][k] * Bs[k][sc + 0];
            a21 += As[ty * FRAG + 2][k] * Bs[k][sc + 1];
            a22 += As[ty * FRAG + 2][k] * Bs[k][sc + 2];
            a23 += As[ty * FRAG + 2][k] * Bs[k][sc + 3];
            a30 += As[ty * FRAG + 3][k] * Bs[k][sc + 0];
            a31 += As[ty * FRAG + 3][k] * Bs[k][sc + 1];
            a32 += As[ty * FRAG + 3][k] * Bs[k][sc + 2];
            a33 += As[ty * FRAG + 3][k] * Bs[k][sc + 3];
        }

        __syncthreads();
    }

    // --- Store 4x4 output fragment ---
    const int r0 = row;
    const int c0 = col;
    if (r0 + 0 < N && c0 + 0 < N) C[(r0 + 0) * N + (c0 + 0)] = a00;
    if (r0 + 0 < N && c0 + 1 < N) C[(r0 + 0) * N + (c0 + 1)] = a01;
    if (r0 + 0 < N && c0 + 2 < N) C[(r0 + 0) * N + (c0 + 2)] = a02;
    if (r0 + 0 < N && c0 + 3 < N) C[(r0 + 0) * N + (c0 + 3)] = a03;
    if (r0 + 1 < N && c0 + 0 < N) C[(r0 + 1) * N + (c0 + 0)] = a10;
    if (r0 + 1 < N && c0 + 1 < N) C[(r0 + 1) * N + (c0 + 1)] = a11;
    if (r0 + 1 < N && c0 + 2 < N) C[(r0 + 1) * N + (c0 + 2)] = a12;
    if (r0 + 1 < N && c0 + 3 < N) C[(r0 + 1) * N + (c0 + 3)] = a13;
    if (r0 + 2 < N && c0 + 0 < N) C[(r0 + 2) * N + (c0 + 0)] = a20;
    if (r0 + 2 < N && c0 + 1 < N) C[(r0 + 2) * N + (c0 + 1)] = a21;
    if (r0 + 2 < N && c0 + 2 < N) C[(r0 + 2) * N + (c0 + 2)] = a22;
    if (r0 + 2 < N && c0 + 3 < N) C[(r0 + 2) * N + (c0 + 3)] = a23;
    if (r0 + 3 < N && c0 + 0 < N) C[(r0 + 3) * N + (c0 + 0)] = a30;
    if (r0 + 3 < N && c0 + 1 < N) C[(r0 + 3) * N + (c0 + 1)] = a31;
    if (r0 + 3 < N && c0 + 2 < N) C[(r0 + 3) * N + (c0 + 2)] = a32;
    if (r0 + 3 < N && c0 + 3 < N) C[(r0 + 3) * N + (c0 + 3)] = a33;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    if (N <= 0) return;
    dim3 block(TILE / FRAG, TILE / FRAG);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
