84	    // --- Store 4x4 output fragment ---
85	    const int r0 = row;
86	    const int c0 = col;
87	    if (r0 + 0 < N && c0 + 0 < N) C[(r0 + 0) * N + (c0 + 0)] = a00;
88	    if (r0 + 0 < N && c0 + 1 < N) C[(r0 + 0) * N + (c0 + 1)] = a01;
89	    if (r0 + 0 < N && c0 + 2 < N) C[(r0 + 0) * N + (c0 + 2)] = a02;
90	    if (r0 + 0 < N && c0 + 3 < N) C[(r0 + 0) * N + (c0 + 3)] = a03;
91	    if (r0 + 1 < N && c0 + 0 < N) C[(r0 + 1) * N + (c0 + 0)] = a10;
92	    if (r0 + 1 < N && c0 + 1 < N) C[(r0 + 1) * N + (c0 + 1)] = a11;
93	    if (r0 + 1 < N && c0 + 2 < N) C[(r0 + 1) * N + (c0 + 2)] = a12;
94	    if (r0 + 1 < N && c0 + 3 < N) C[(r0 + 1) * N + (c0 + 3)] = a13;
95	    if (r0 + 2 < N && c0 + 0 < N) C[(r0 + 2) * N + (c0 + 0)] = a20;
96	    if (r0 + 2 < N && c0 + 1 < N) C[(r0 + 2) * N + (c0 + 1)] = a21;
97	    if (r0 + 2 < N && c0 + 2 < N) C[(r0 + 2) * N + (c0 + 2)] = a22;
98	    if (r0 + 2 < N && c0 + 3 < N) C[(r0 + 2) * N + (c0 + 3)] = a23;
99	    if (r0 + 3 < N && c0 + 0 < N) C[(r0 + 3) * N + (c0 + 0)] = a30;
100	    if (r0 + 3 < N && c0 + 1 < N) C[(r0 + 3) * N + (c0 + 1)] = a31;
101	    if (r0 + 3 < N && c0 + 2 < N) C[(r0 + 3) * N + (c0 + 2)] = a32;
102	    if (r0 + 3 < N && c0 + 3 < N) C[(r0 + 3) * N + (c0 + 3)] = a33;
103	}
