105	void launchGemm(const float* dA, const float* dB, float* dC, int N) {
106	    if (N <= 0) return;
107	    dim3 block(TILE / FRAG, TILE / FRAG);
108	    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
109	    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
110	}
